[
  {
    "schema_name": "public",
    "view_name": "v_client_compliance_summary",
    "relation_type": "VIEW",
    "definition": " WITH all_trackers AS (\n         SELECT income_tax_tracker.client_id,\n            income_tax_tracker.fy_label,\n            income_tax_tracker.status,\n            'Income Tax'::text AS category,\n            COALESCE(income_tax_tracker.individual_due_date, income_tax_tracker.extended_due_date, income_tax_tracker.standard_due_date) AS due_date\n           FROM income_tax_tracker\n        UNION ALL\n         SELECT gst_tracker.client_id,\n            gst_tracker.fy_label,\n            gst_tracker.status,\n            'GST'::text AS text,\n            COALESCE(gst_tracker.individual_due_date, gst_tracker.extended_due_date, gst_tracker.standard_due_date) AS \"coalesce\"\n           FROM gst_tracker\n        UNION ALL\n         SELECT tds_tracker.client_id,\n            tds_tracker.fy_label,\n            tds_tracker.status,\n            'TDS'::text AS text,\n            COALESCE(tds_tracker.individual_due_date, tds_tracker.extended_due_date, tds_tracker.standard_due_date) AS \"coalesce\"\n           FROM tds_tracker\n        UNION ALL\n         SELECT roc_tracker.client_id,\n            roc_tracker.fy_label,\n            roc_tracker.status,\n            'ROC'::text AS text,\n            COALESCE(roc_tracker.individual_due_date, roc_tracker.extended_due_date, roc_tracker.standard_due_date) AS \"coalesce\"\n           FROM roc_tracker\n        UNION ALL\n         SELECT llp_tracker.client_id,\n            llp_tracker.fy_label,\n            llp_tracker.status,\n            'LLP'::text AS text,\n            COALESCE(llp_tracker.individual_due_date, llp_tracker.extended_due_date, llp_tracker.standard_due_date) AS \"coalesce\"\n           FROM llp_tracker\n        UNION ALL\n         SELECT audit_tracker.client_id,\n            audit_tracker.fy_label,\n            audit_tracker.status,\n            'Audit'::text AS text,\n            COALESCE(audit_tracker.individual_due_date, audit_tracker.extended_due_date, audit_tracker.standard_due_date) AS \"coalesce\"\n           FROM audit_tracker\n        UNION ALL\n         SELECT accounting_tracker.client_id,\n            accounting_tracker.fy_label,\n            accounting_tracker.status,\n            'Accounting'::text AS text,\n            NULL::date AS date\n           FROM accounting_tracker\n        UNION ALL\n         SELECT payroll_tracker.client_id,\n            payroll_tracker.fy_label,\n            payroll_tracker.status,\n            'Payroll'::text AS text,\n            COALESCE(payroll_tracker.individual_due_date, payroll_tracker.extended_due_date, payroll_tracker.standard_due_date) AS \"coalesce\"\n           FROM payroll_tracker\n        UNION ALL\n         SELECT trust_ngo_tracker.client_id,\n            trust_ngo_tracker.fy_label,\n            trust_ngo_tracker.status,\n            'Trust/NGO'::text AS text,\n            COALESCE(trust_ngo_tracker.individual_due_date, trust_ngo_tracker.extended_due_date, trust_ngo_tracker.standard_due_date) AS \"coalesce\"\n           FROM trust_ngo_tracker\n        UNION ALL\n         SELECT notice_tracker.client_id,\n            notice_tracker.fy_label,\n            notice_tracker.status,\n            'Notice'::text AS text,\n            COALESCE(notice_tracker.individual_due_date, notice_tracker.extended_due_date, notice_tracker.response_due_date) AS \"coalesce\"\n           FROM notice_tracker\n        )\n SELECT client_id,\n    fy_label,\n    count(*) AS total_compliances,\n    count(*) FILTER (WHERE status = ANY (ARRAY['Filed'::compliance_status_enum, 'Completed'::compliance_status_enum])) AS completed,\n    count(*) FILTER (WHERE status = 'Overdue'::compliance_status_enum OR due_date < CURRENT_DATE AND (status <> ALL (ARRAY['Filed'::compliance_status_enum, 'Completed'::compliance_status_enum, 'Closed'::compliance_status_enum, 'Not Applicable'::compliance_status_enum]))) AS overdue,\n    count(*) FILTER (WHERE (status <> ALL (ARRAY['Filed'::compliance_status_enum, 'Completed'::compliance_status_enum, 'Overdue'::compliance_status_enum, 'Closed'::compliance_status_enum, 'Not Applicable'::compliance_status_enum])) AND (due_date IS NULL OR due_date >= CURRENT_DATE)) AS pending,\n    count(*) FILTER (WHERE due_date >= CURRENT_DATE AND due_date <= (CURRENT_DATE + 7) AND (status <> ALL (ARRAY['Filed'::compliance_status_enum, 'Completed'::compliance_status_enum, 'Closed'::compliance_status_enum, 'Not Applicable'::compliance_status_enum]))) AS due_soon,\n    count(*) FILTER (WHERE status = ANY (ARRAY['Not Applicable'::compliance_status_enum, 'Closed'::compliance_status_enum])) AS not_applicable,\n    count(*) FILTER (WHERE status = 'Waiting for Client'::compliance_status_enum) AS waiting_client,\n    count(*) FILTER (WHERE status = 'Partner Approval Pending'::compliance_status_enum) AS partner_approval_pending,\n    count(*) FILTER (WHERE status = 'Reviewed'::compliance_status_enum) AS review_pending,\n    count(*) FILTER (WHERE status = 'Filing Pending'::compliance_status_enum) AS filing_pending\n   FROM all_trackers\n  GROUP BY client_id, fy_label;"
  },
  {
    "schema_name": "public",
    "view_name": "v_firm_dashboard",
    "relation_type": "VIEW",
    "definition": " WITH all_trackers AS (\n         SELECT income_tax_tracker.client_id,\n            income_tax_tracker.status,\n            'Income Tax'::text AS category,\n            COALESCE(income_tax_tracker.individual_due_date, income_tax_tracker.extended_due_date, income_tax_tracker.standard_due_date) AS due_date\n           FROM income_tax_tracker\n        UNION ALL\n         SELECT gst_tracker.client_id,\n            gst_tracker.status,\n            'GST'::text AS text,\n            COALESCE(gst_tracker.individual_due_date, gst_tracker.extended_due_date, gst_tracker.standard_due_date) AS \"coalesce\"\n           FROM gst_tracker\n        UNION ALL\n         SELECT tds_tracker.client_id,\n            tds_tracker.status,\n            'TDS'::text AS text,\n            COALESCE(tds_tracker.individual_due_date, tds_tracker.extended_due_date, tds_tracker.standard_due_date) AS \"coalesce\"\n           FROM tds_tracker\n        UNION ALL\n         SELECT roc_tracker.client_id,\n            roc_tracker.status,\n            'ROC'::text AS text,\n            COALESCE(roc_tracker.individual_due_date, roc_tracker.extended_due_date, roc_tracker.standard_due_date) AS \"coalesce\"\n           FROM roc_tracker\n        UNION ALL\n         SELECT llp_tracker.client_id,\n            llp_tracker.status,\n            'LLP'::text AS text,\n            COALESCE(llp_tracker.individual_due_date, llp_tracker.extended_due_date, llp_tracker.standard_due_date) AS \"coalesce\"\n           FROM llp_tracker\n        UNION ALL\n         SELECT audit_tracker.client_id,\n            audit_tracker.status,\n            'Audit'::text AS text,\n            COALESCE(audit_tracker.individual_due_date, audit_tracker.extended_due_date, audit_tracker.standard_due_date) AS \"coalesce\"\n           FROM audit_tracker\n        UNION ALL\n         SELECT accounting_tracker.client_id,\n            accounting_tracker.status,\n            'Accounting'::text AS text,\n            NULL::date AS date\n           FROM accounting_tracker\n        UNION ALL\n         SELECT payroll_tracker.client_id,\n            payroll_tracker.status,\n            'Payroll'::text AS text,\n            COALESCE(payroll_tracker.individual_due_date, payroll_tracker.extended_due_date, payroll_tracker.standard_due_date) AS \"coalesce\"\n           FROM payroll_tracker\n        UNION ALL\n         SELECT trust_ngo_tracker.client_id,\n            trust_ngo_tracker.status,\n            'Trust/NGO'::text AS text,\n            COALESCE(trust_ngo_tracker.individual_due_date, trust_ngo_tracker.extended_due_date, trust_ngo_tracker.standard_due_date) AS \"coalesce\"\n           FROM trust_ngo_tracker\n        UNION ALL\n         SELECT notice_tracker.client_id,\n            notice_tracker.status,\n            'Notice'::text AS text,\n            COALESCE(notice_tracker.individual_due_date, notice_tracker.extended_due_date, notice_tracker.response_due_date) AS \"coalesce\"\n           FROM notice_tracker\n        )\n SELECT category,\n    count(*) AS total,\n    count(*) FILTER (WHERE status = ANY (ARRAY['Filed'::compliance_status_enum, 'Completed'::compliance_status_enum])) AS completed,\n    count(*) FILTER (WHERE status = 'Overdue'::compliance_status_enum OR due_date < CURRENT_DATE AND (status <> ALL (ARRAY['Filed'::compliance_status_enum, 'Completed'::compliance_status_enum, 'Closed'::compliance_status_enum, 'Not Applicable'::compliance_status_enum]))) AS overdue,\n    count(*) FILTER (WHERE (status <> ALL (ARRAY['Filed'::compliance_status_enum, 'Completed'::compliance_status_enum, 'Overdue'::compliance_status_enum, 'Closed'::compliance_status_enum, 'Not Applicable'::compliance_status_enum])) AND (due_date IS NULL OR due_date >= CURRENT_DATE)) AS pending,\n    count(*) FILTER (WHERE due_date >= CURRENT_DATE AND due_date <= (CURRENT_DATE + 7) AND (status <> ALL (ARRAY['Filed'::compliance_status_enum, 'Completed'::compliance_status_enum, 'Closed'::compliance_status_enum, 'Not Applicable'::compliance_status_enum]))) AS due_in_7_days,\n    count(*) FILTER (WHERE status = 'Waiting for Client'::compliance_status_enum) AS waiting_client,\n    count(*) FILTER (WHERE status = 'Partner Approval Pending'::compliance_status_enum) AS partner_approval_pending\n   FROM all_trackers\n  GROUP BY category;"
  },
  {
    "schema_name": "public",
    "view_name": "v_overdue_ageing",
    "relation_type": "VIEW",
    "definition": " WITH all_overdue AS (\n         SELECT income_tax_tracker.client_id,\n            'Income Tax'::text AS category,\n            COALESCE(income_tax_tracker.individual_due_date, income_tax_tracker.extended_due_date, income_tax_tracker.standard_due_date) AS due_date\n           FROM income_tax_tracker\n          WHERE (income_tax_tracker.status <> ALL (ARRAY['Filed'::compliance_status_enum, 'Completed'::compliance_status_enum, 'Closed'::compliance_status_enum, 'Not Applicable'::compliance_status_enum])) AND COALESCE(income_tax_tracker.individual_due_date, income_tax_tracker.extended_due_date, income_tax_tracker.standard_due_date) < CURRENT_DATE\n        UNION ALL\n         SELECT gst_tracker.client_id,\n            'GST'::text AS text,\n            COALESCE(gst_tracker.individual_due_date, gst_tracker.extended_due_date, gst_tracker.standard_due_date) AS \"coalesce\"\n           FROM gst_tracker\n          WHERE (gst_tracker.status <> ALL (ARRAY['Filed'::compliance_status_enum, 'Completed'::compliance_status_enum, 'Closed'::compliance_status_enum, 'Not Applicable'::compliance_status_enum])) AND COALESCE(gst_tracker.individual_due_date, gst_tracker.extended_due_date, gst_tracker.standard_due_date) < CURRENT_DATE\n        UNION ALL\n         SELECT tds_tracker.client_id,\n            'TDS'::text AS text,\n            COALESCE(tds_tracker.individual_due_date, tds_tracker.extended_due_date, tds_tracker.standard_due_date) AS \"coalesce\"\n           FROM tds_tracker\n          WHERE (tds_tracker.status <> ALL (ARRAY['Filed'::compliance_status_enum, 'Completed'::compliance_status_enum, 'Closed'::compliance_status_enum, 'Not Applicable'::compliance_status_enum])) AND COALESCE(tds_tracker.individual_due_date, tds_tracker.extended_due_date, tds_tracker.standard_due_date) < CURRENT_DATE\n        UNION ALL\n         SELECT roc_tracker.client_id,\n            'ROC'::text AS text,\n            COALESCE(roc_tracker.individual_due_date, roc_tracker.extended_due_date, roc_tracker.standard_due_date) AS \"coalesce\"\n           FROM roc_tracker\n          WHERE (roc_tracker.status <> ALL (ARRAY['Filed'::compliance_status_enum, 'Completed'::compliance_status_enum, 'Closed'::compliance_status_enum, 'Not Applicable'::compliance_status_enum])) AND COALESCE(roc_tracker.individual_due_date, roc_tracker.extended_due_date, roc_tracker.standard_due_date) < CURRENT_DATE\n        UNION ALL\n         SELECT notice_tracker.client_id,\n            'Notice'::text AS text,\n            COALESCE(notice_tracker.individual_due_date, notice_tracker.extended_due_date, notice_tracker.response_due_date) AS \"coalesce\"\n           FROM notice_tracker\n          WHERE (notice_tracker.status <> ALL (ARRAY['Filed'::compliance_status_enum, 'Completed'::compliance_status_enum, 'Closed'::compliance_status_enum, 'Not Applicable'::compliance_status_enum])) AND COALESCE(notice_tracker.individual_due_date, notice_tracker.extended_due_date, notice_tracker.response_due_date) < CURRENT_DATE\n        )\n SELECT client_id,\n    category,\n    due_date,\n    CURRENT_DATE - due_date AS days_overdue,\n        CASE\n            WHEN (CURRENT_DATE - due_date) >= 0 AND (CURRENT_DATE - due_date) <= 7 THEN '0-7 Days'::text\n            WHEN (CURRENT_DATE - due_date) >= 8 AND (CURRENT_DATE - due_date) <= 15 THEN '8-15 Days'::text\n            WHEN (CURRENT_DATE - due_date) >= 16 AND (CURRENT_DATE - due_date) <= 30 THEN '16-30 Days'::text\n            ELSE 'More than 30 Days'::text\n        END AS ageing_bucket\n   FROM all_overdue;"
  }
]